patient_data={}; labels={}
for sh,rows in all_rows.items():
    for i,row in enumerate(rows):
        for c,v in enumerate(row):
            if isinstance(v,str) and pid_re.match(v.strip()):
                pid=v.strip().upper()
                patient_data.setdefault(pid,{})[sh]=(i,row)
                break
        for c,v in enumerate(row):
            if isinstance(v,str) and v.strip().upper() in label_map and pid not in labels:
